/* ─── 1. BMI / WEIGHT ANALYSIS ──────────────────────────────── */
function skGetBMIData(weight, height, age) {
    if (!weight || !height) return null;
    const h = height / 100;
    const bmi = weight / (h * h);
    const bmiFixed = parseFloat(bmi.toFixed(1));
    let category, color, emoji, advice, range;
    if (bmiFixed < 18.5) {
        category = 'Underweight'; color = '#60a5fa'; emoji = '⚠️'; range = '< 18.5';
        advice = 'Your weight is below the healthy range for your height. Focus on nutrient-dense foods to build strength and support skin health. Include healthy fats, proteins, and complex carbs.';
    } else if (bmiFixed < 25) {
        category = 'Healthy Weight'; color = '#34d399'; emoji = '✅'; range = '18.5 – 24.9';
        advice = 'Your weight is in the ideal range! This supports optimal skin function, hormone balance, and energy. Keep maintaining your balanced lifestyle.';
    } else if (bmiFixed < 30) {
        category = 'Overweight'; color = '#fbbf24'; emoji = '💛'; range = '25 – 29.9';
        advice = 'Your BMI is slightly above the healthy range. Small lifestyle changes in diet and movement can make a big difference for your skin glow and overall health.';
    } else {
        category = 'Obese (Class I+)'; color = '#f87171'; emoji = '🩺'; range = '≥ 30';
        advice = 'Your BMI suggests consulting a healthcare provider for a personalised plan. Remember, every body is beautiful — small consistent steps lead to big changes.';
    }
    // Ideal weight range for this height
    const idealLow = (18.5 * h * h).toFixed(1);
    const idealHigh = (24.9 * h * h).toFixed(1);
    return { bmi: bmiFixed, category, color, emoji, advice, range, idealLow, idealHigh };
}

