/* ─── 5. INJECT BMI SECTION INTO DASHBOARD ───────────────────── */
function skInjectBMISection() {
    const p = window.skProfile || {};
    if (!p.weight || !p.height) return;
    const data = skGetBMIData(p.weight, p.height, p.age);
    if (!data) return;

    const existing = document.getElementById('skinoraBMISection');
    if (existing) existing.remove();

    const pct = Math.min(100, Math.max(0, ((data.bmi - 15) / (40 - 15)) * 100));

    const html = `
    <div id="skinoraBMISection" class="sk3d-bmi-section">
        <div class="sk3d-section-badge">⚡ HEALTH ANALYSIS</div>
        <h3 class="sk3d-section-title">Your Body Intelligence</h3>
        <div class="sk3d-bmi-card">
            <div class="sk3d-bmi-orb" style="--bmi-color:${data.color}">
                <div class="sk3d-bmi-orb-inner">
                    <div class="sk3d-bmi-number">${data.bmi}</div>
                    <div class="sk3d-bmi-label">BMI</div>
                </div>
            </div>
            <div class="sk3d-bmi-info">
                <div class="sk3d-bmi-status" style="color:${data.color}">${data.emoji} ${data.category}</div>
                <div class="sk3d-bmi-range">Range: <strong>${data.range}</strong></div>
                <p class="sk3d-bmi-advice">${data.advice}</p>
                <div class="sk3d-bmi-ideal">
                    <span>Ideal weight for your height:</span>
                    <strong>${data.idealLow} – ${data.idealHigh} kg</strong>
                </div>
            </div>
        </div>
        <div class="sk3d-bmi-bar-wrap">
            <div class="sk3d-bmi-bar-labels">
                <span>Underweight<br><small>&lt;18.5</small></span>
                <span>Healthy<br><small>18.5–24.9</small></span>
                <span>Overweight<br><small>25–29.9</small></span>
                <span>Obese<br><small>30+</small></span>
            </div>
            <div class="sk3d-bmi-track">
                <div class="sk3d-bmi-fill-under" style="width:23.5%"></div>
                <div class="sk3d-bmi-fill-healthy" style="width:26%"></div>
                <div class="sk3d-bmi-fill-over" style="width:25%"></div>
                <div class="sk3d-bmi-fill-obese" style="width:25.5%"></div>
                <div class="sk3d-bmi-marker" style="left:${pct}%">
                    <div class="sk3d-bmi-marker-pin"></div>
                    <div class="sk3d-bmi-marker-label">${data.bmi}</div>
                </div>
            </div>
        </div>
    </div>`;

    const dashGrid = document.querySelector('#dashboard .grid');
    if (dashGrid) dashGrid.insertAdjacentHTML('beforebegin', html);
}

/* ─── 6. INJECT PERSONALISED DIET PLAN ───────────────────────── */
function skInjectDietPlan() {
    const p = window.skProfile || {};
    const skin = p.skinType || 'normal';
    const plan = skDietPlans[skin] || skDietPlans.normal;
    const hasSmoking = p.smoking === 'smoke' || p.smoking === 'vape';

    const existing = document.getElementById('skinoraPersonalDiet');
    if (existing) existing.remove();

    const mealsHTML = plan.meals.map((m, i) => `
        <div class="sk3d-meal-card" style="animation-delay:${i * 0.08}s">
            <div class="sk3d-meal-time">${m.time}</div>
            <div class="sk3d-meal-icon">${m.icon}</div>
            <div class="sk3d-meal-content">
                <div class="sk3d-meal-name">${m.meal}</div>
                <ul class="sk3d-meal-items">
                    ${m.items.map(item => `<li>${item}</li>`).join('')}
                </ul>
            </div>
        </div>`).join('');

    const smokingSection = hasSmoking ? `
        <div class="sk3d-pcos-alert">
            <div class="sk3d-pcos-badge">🚬 Smoker/Vaper Skin Tips</div>
            <div class="sk3d-pcos-grid">
                <div>
                    <h5>✅ Add These</h5>
                    <ul>
                        <li>Vitamin C (1000mg/day) — smoking depletes it fast</li>
                        <li>Antioxidant-rich foods: berries, green tea, dark chocolate</li>
                        <li>Collagen-boosting foods: bone broth, eggs, citrus</li>
                        <li>Zinc: pumpkin seeds, chickpeas — repairs skin barrier</li>
                        <li>Hydrate more — nicotine dehydrates skin severely</li>
                    </ul>
                </div>
                <div>
                    <h5>🚫 Avoid These</h5>
                    <ul>
                        <li>Excess alcohol — doubles oxidative skin damage</li>
                        <li>Sugary drinks — worsens glycation and wrinkle formation</li>
                        <li>Processed foods high in trans fats</li>
                        <li>Skipping SPF — smoke + UV is a major aging combo</li>
                    </ul>
                </div>
            </div>
            <p class="sk3d-pcos-tip">💡 Smoking accelerates skin aging by up to 10 years. Antioxidants and hydration are your best countermeasures.</p>
        </div>` : '';

    const html = `
    <div id="skinoraPersonalDiet" class="sk3d-diet-plan-section">
        <div class="sk3d-section-badge">🍽️ PERSONALISED PLAN</div>
        <h3 class="sk3d-section-title">${plan.skinTitle}</h3>
        <p class="sk3d-section-desc">${plan.skinDesc}</p>
        
        <div class="sk3d-meal-timeline">
            ${mealsHTML}
        </div>
        
        <div class="sk3d-diet-avoid">
            <h4>🚫 Foods To Avoid</h4>
            <div class="sk3d-avoid-pills">
                ${plan.avoid.map(a => `<span class="sk3d-avoid-pill">${a}</span>`).join('')}
            </div>
        </div>
        
        <div class="sk3d-superfoods">
            <h4>⚡ Your Skin Superfoods</h4>
            <div class="sk3d-superfood-row">
                ${plan.superfoods.map(sf => `<div class="sk3d-superfood">${sf}</div>`).join('')}
            </div>
        </div>
        
        ${smokingSection}
    </div>`;

    const dietContainer = document.querySelector('#diet .container');
    if (dietContainer) {
        const dietTabs = dietContainer.querySelector('.diet-tabs');
        if (dietTabs) dietTabs.insertAdjacentHTML('beforebegin', html);
    }
}

/* ─── 7. BUILD COLOUR SWATCHES ────────────────────────────────── */
function skInjectColourSwatches() {
    const p = window.skProfile || {};
    const undertone = p.undertone;
    if (!undertone || !skColourSwatches[undertone]) return;

    const existing = document.getElementById('skinoraColourSwatches');
    if (existing) existing.remove();

    const sw = skColourSwatches[undertone];

    const buildSwatchRow = (colors, labels, matches) => colors.map((c, i) => {
        const isAvoid = matches && matches[i] === false;
        return `<div class="sk3d-swatch-item ${isAvoid ? 'sk3d-swatch-avoid' : ''}">
            <div class="sk3d-swatch-circle" style="background:${c}">${isAvoid ? '✕' : ''}</div>
            <span>${labels[i]}</span>
        </div>`;
    }).join('');

    const html = `
    <div id="skinoraColourSwatches" class="sk3d-colour-section">
        <div class="sk3d-section-badge">🎨 YOUR PALETTE</div>
        <h3 class="sk3d-section-title">Colours That Make You Glow ✨</h3>
        <p class="sk3d-section-desc">Personalised for your <strong>${undertone}</strong> undertone</p>
        
        <div class="sk3d-colour-block">
            <h4>👔 Clothing Palette</h4>
            <div class="sk3d-swatch-grid">${buildSwatchRow(sw.clothing, sw.labels)}</div>
        </div>
        
        <div class="sk3d-colour-block">
            <h4>🎨 Colour Shades</h4>
            <div class="sk3d-swatch-grid">${buildSwatchRow(sw.lipstick, sw.lipLabels)}</div>
        </div>
        
        <div class="sk3d-colour-block">
            <h4>🪙 Accessories</h4>
            <div class="sk3d-swatch-grid">${buildSwatchRow(sw.jewelry, sw.jwLabels, sw.jwMatch)}</div>
        </div>
    </div>`;

    const colourContainer = document.querySelector('#colour-theory .container');
    if (colourContainer) {
        const undertoneSection = colourContainer.querySelector('.undertone-section');
        if (undertoneSection) undertoneSection.insertAdjacentHTML('beforebegin', html);
    }
}

/* ─── 8. BUILD SKINCARE PAGE ─────────────────────────────────── */
function skBuildSkincareSection() {
    const p = window.skProfile || {};
    const skin = p.skinType || 'normal';
    const routine = skSkincareRoutines[skin] || skSkincareRoutines.normal;
    const skincarePage = document.getElementById('skin-care');
    if (!skincarePage) return;

    const amPM = (type) => routine.products[type].map((item, i) => `
        <div class="sk3d-step-item" style="animation-delay:${i*0.07}s">
            <div class="sk3d-step-num">${i+1}</div>
            <div class="sk3d-step-text">${item}</div>
        </div>`).join('');

    const dayCards = routine.weeklyRoutine.map((d, i) => `
        <div class="sk3d-day-card" style="animation-delay:${i*0.06}s">
            <div class="sk3d-day-header">
                <span class="sk3d-day-icon">${d.icon}</span>
                <div>
                    <div class="sk3d-day-name">${d.day}</div>
                    <div class="sk3d-day-focus">${d.focus}</div>
                </div>
                <div class="sk3d-day-num">Day ${i+1}</div>
            </div>
            <ul class="sk3d-day-steps">
                ${d.steps.map(s => `<li>• ${s}</li>`).join('')}
            </ul>
        </div>`).join('');

    skincarePage.innerHTML = `
    <div class="sk3d-skincare-container">
        <div class="sk3d-section-badge">🌸 YOUR ROUTINE</div>
        <h2 class="sk3d-page-title">${routine.title}</h2>
        <p class="sk3d-page-desc">${routine.description}</p>

        <!-- Facewash recommendation -->
        <div class="sk3d-facewash-card">
            <div class="sk3d-facewash-icon">🧴</div>
            <div>
                <div class="sk3d-facewash-label">Recommended Face Wash</div>
                <div class="sk3d-facewash-text">${routine.facewash}</div>
            </div>
        </div>
        
        <!-- AM/PM Toggle -->
        <div class="sk3d-ampm-toggle">
            <button class="sk3d-ampm-btn active" id="skAmBtn" onclick="skToggleAMPM('AM')">☀️ Morning (AM)</button>
            <button class="sk3d-ampm-btn" id="skPmBtn" onclick="skToggleAMPM('PM')">🌙 Night (PM)</button>
        </div>
        
        <div class="sk3d-steps-container" id="skAMSteps">
            <h4>☀️ Morning Routine</h4>
            ${amPM('AM')}
        </div>
        <div class="sk3d-steps-container" id="skPMSteps" style="display:none">
            <h4>🌙 Night Routine</h4>
            ${amPM('PM')}
        </div>
        
        <!-- Day-wise weekly cards -->
        <div class="sk3d-weekly-header">
            <div class="sk3d-section-badge">📅 WEEKLY PLAN</div>
            <h3>Your 7-Day Glow Schedule</h3>
        </div>
        <div class="sk3d-days-grid">
            ${dayCards}
        </div>
        
        <!-- Pro Tips -->
        <div class="sk3d-tips-section">
            <h4>💡 Pro Tips for Your Skin Type</h4>
            <div class="sk3d-tips-grid">
                ${routine.tips.map(t => `<div class="sk3d-tip-card">✨ ${t}</div>`).join('')}
            </div>
        </div>
    </div>`;
}

function skToggleAMPM(type) {
    const am = document.getElementById('skAMSteps');
    const pm = document.getElementById('skPMSteps');
    const amBtn = document.getElementById('skAmBtn');
    const pmBtn = document.getElementById('skPmBtn');
    if (type === 'AM') {
        if(am) am.style.display = '';
        if(pm) pm.style.display = 'none';
        if(amBtn) amBtn.classList.add('active');
        if(pmBtn) pmBtn.classList.remove('active');
    } else {
        if(am) am.style.display = 'none';
        if(pm) pm.style.display = '';
        if(amBtn) amBtn.classList.remove('active');
        if(pmBtn) pmBtn.classList.add('active');
    }
}

/* ─── HOOK INTO EXISTING skEnter/skPopulateProfile ─────────────── */
document.addEventListener('DOMContentLoaded', function() {
    // Patch skEnter to also run our sections
    var origEnter = window.skEnter;
    window.skEnter = function() {
        if (origEnter) origEnter();
        setTimeout(function() {
            skRunEnhancements();
        }, 800);
    };
    
    // Patch skPopulateProfile
    var origPopulate = window.skPopulateProfile;
    window.skPopulateProfile = function() {
        if (origPopulate) origPopulate();
        setTimeout(skRunEnhancements, 100);
    };
    
    // Run immediately if already onboarded
    setTimeout(function() {
        if (window.skProfile && window.skProfile.skinType) {
            skRunEnhancements();
        }
    }, 500);
});

function skRunEnhancements() {
    skInjectBMISection();
    skInjectDietPlan();
    skInjectColourSwatches();
    skBuildSkincareSection();
}

// Expose toggle function globally
window.skToggleAMPM = skToggleAMPM;

/* ─── XP BANNER SHOW ───────────────────────────────────────── */
function skShowXPBanner() {
    const p = window.skProfile || {};
    const banner = document.getElementById('skXPBanner');
    if (!banner) return;
    banner.style.display = 'flex';
    const title = document.getElementById('skXPTitle');
    const sub = document.getElementById('skXPSub');
    if (title && p.skinType) {
        const skinEmoji = {oily:'💧',dry:'🌵',combination:'⚖️',sensitive:'🌸',normal:'✨'};
        title.textContent = `${skinEmoji[p.skinType] || '✨'} Welcome back, King!`;
    }
    if (sub && p.age && p.height && p.weight) {
        const h = p.height/100;
        const bmi = (p.weight/(h*h)).toFixed(1);
        sub.textContent = `BMI: ${bmi} · ${p.skinType} skin · ${p.undertone || 'unknown'} undertone · All sections personalised 💪`;
    }
}

// Patch runEnhancements to also show banner
var _origRun = window.skRunEnhancements || function(){};
window.skRunEnhancements = function() {
    _origRun();
    skShowXPBanner();
};
// Re-hook
document.addEventListener('DOMContentLoaded', function() {
    setTimeout(function() {
        if (window.skProfile && window.skProfile.skinType) {
            skShowXPBanner();
        }
    }, 600);
});
