function renderDiet(category) {
    const grid = document.getElementById('drinksGrid');
    const items = dietData[category];
    grid.innerHTML = '';

    const photoCategories = ['fruits', 'veggies', 'oats', 'clearfoods'];

    if (photoCategories.includes(category)) {
        grid.className = 'drinks-grid fruit-grid';
        items.forEach((item, i) => {
            const card = document.createElement('div');
            card.className = 'drink-card fruit-card';
            card.style.animationDelay = `${i * 0.06}s`;

            const imgMap = category === 'fruits' ? fruitImages
                         : category === 'veggies' ? veggieImages
                         : category === 'clearfoods' ? clearfoodsImages
                         : oatImages;
            const imgSrc = imgMap[item.name] || '';

            card.innerHTML = `
                <div class="fruit-img-wrap">
                    ${imgSrc
                        ? `<img src="${imgSrc}" alt="${item.name}" class="fruit-photo" />`
                        : `<div class="fruit-emoji-fallback">${item.emoji}</div>`}
                    <div class="fruit-img-overlay"></div>
                </div>
                <div class="fruit-card-body">
                    <div class="drink-name">${item.name}</div>
                    <div class="drink-sub">${item.subtitle}</div>
                    <div class="drink-tap">Tap to explore →</div>
                </div>
            `;
            card.addEventListener('click', () => openDietModal(item, category));
            grid.appendChild(card);
        });
    } else {
        grid.className = 'drinks-grid';
        items.forEach((item, i) => {
            const card = document.createElement('div');
            card.className = 'drink-card';
            card.style.animationDelay = `${i * 0.06}s`;
            card.innerHTML = `
                <div class="drink-emoji">${item.emoji}</div>
                <div class="drink-name">${item.name}</div>
                <div class="drink-sub">${item.subtitle}</div>
                <div class="drink-tap">Tap to explore →</div>
            `;
            card.addEventListener('click', () => openDietModal(item, category));
            grid.appendChild(card);
        });
    }
}

function openDietModal(item, category) {
    document.getElementById('modalEmoji').textContent = item.emoji;
    document.getElementById('modalTitle').textContent = item.name;
    document.getElementById('modalBenefit').textContent = item.benefit;

    const label = document.getElementById('modalIngredientsLabel');
    const ul = document.getElementById('modalIngredients');

    if (category === 'oats') {
        label.textContent = '🛒 Ingredients:';
    } else {
        label.textContent = '🌿 Skin Benefits:';
    }

    ul.innerHTML = '';
    item.details.forEach(d => {
        const li = document.createElement('li');
        li.textContent = d;
        ul.appendChild(li);
    });

    document.getElementById('modalTip').textContent = item.tip;
    document.getElementById('recipeModal').classList.add('show');
    document.getElementById('modalOverlay').classList.add('show');
    document.body.style.overflow = 'hidden';
}

function closeDietModal() {
    document.getElementById('recipeModal').classList.remove('show');
    document.getElementById('modalOverlay').classList.remove('show');
    document.body.style.overflow = '';
}

document.getElementById('modalClose').addEventListener('click', closeDietModal);
document.getElementById('modalOverlay').addEventListener('click', closeDietModal);

let currentDietCategory = 'fruits';

document.querySelectorAll('.diet-tab').forEach(tab => {
    tab.addEventListener('click', () => {
        document.querySelectorAll('.diet-tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        currentDietCategory = tab.dataset.category;
        renderDiet(currentDietCategory);
    });
});

renderDiet('fruits');
