// ── Water Tracker Logic ──
let hgGlassCount = 0;

function initHgTracker() {
    const row = document.getElementById('hgGlassesRow');
    row.innerHTML = '';
    for (let i = 0; i < 8; i++) {
        const g = document.createElement('span');
        g.className = 'hg-glass' + (i < hgGlassCount ? ' filled' : '');
        g.textContent = '💧';
        g.dataset.index = i;
        g.addEventListener('click', () => {
            const idx = parseInt(g.dataset.index);
            hgGlassCount = idx < hgGlassCount ? idx : idx + 1;
            document.getElementById('hgGlassCount').textContent = hgGlassCount;
            document.querySelectorAll('.hg-glass').forEach((el, j) => {
                el.classList.toggle('filled', j < hgGlassCount);
            });
        });
        row.appendChild(g);
    }
}

// ── Render Cards ──
function renderHydraGlow(category) {
    const grid = document.getElementById('hgGrid');
    grid.innerHTML = '';
    const items = hydraGlowData[category];
    items.forEach((item, i) => {
        const card = document.createElement('div');
        card.className = 'hg-card' + (item.isSkip ? ' hg-skip' : '');
        card.style.animationDelay = `${i * 0.07}s`;
        const imgSrc = hgImages[item.name];
        const mediaHTML = imgSrc
            ? `<div class="hg-card-img-wrap"><img src="${imgSrc}" alt="${item.name}" class="hg-card-img" /><div class="hg-card-img-overlay"></div></div>`
            : `<span class="hg-card-emoji">${item.emoji}</span>`;
        card.innerHTML = `
            ${item.badge ? `<span class="hg-card-badge">${item.badge}</span>` : ''}
            ${mediaHTML}
            <div class="hg-card-body">
                <div class="hg-card-name">${item.name}</div>
                <div class="hg-card-sub">${item.sub}</div>
                <div class="hg-card-tap">Tap to reveal ✨</div>
            </div>
        `;
        card.addEventListener('click', () => openHgModal(item));
        grid.appendChild(card);
    });
}

// ── Modal Logic ──
function openHgModal(item) {
    const imgSrc = hgImages[item.name];
    const emojiEl = document.getElementById('hgModalEmoji');
    if (imgSrc) {
        emojiEl.innerHTML = `<img src="${imgSrc}" alt="${item.name}" class="hg-modal-img" />`;
    } else {
        emojiEl.innerHTML = item.emoji;
        emojiEl.style.fontSize = '3.5rem';
    }
    document.getElementById('hgModalTitle').textContent = item.name;
    document.getElementById('hgModalTagline').textContent = item.tagline;

    const ul = document.getElementById('hgModalIngredients');
    ul.innerHTML = '';
    item.ingredients.forEach(ing => {
        const li = document.createElement('li');
        li.textContent = ing;
        ul.appendChild(li);
    });

    document.getElementById('hgModalTip').textContent = item.tip;

    const skipDiv = document.getElementById('hgModalSkip');
    skipDiv.textContent = item.isSkip ? '🚫 Avoid on empty stomach!' : '';

    document.getElementById('hgModal').classList.add('show');
    document.getElementById('hgModalOverlay').classList.add('show');
    document.body.style.overflow = 'hidden';
}

function closeHgModal() {
    document.getElementById('hgModal').classList.remove('show');
    document.getElementById('hgModalOverlay').classList.remove('show');
    document.body.style.overflow = '';
}

document.getElementById('hgModalClose').addEventListener('click', closeHgModal);
document.getElementById('hgModalOverlay').addEventListener('click', closeHgModal);

// ── Tab Switching ──
document.querySelectorAll('.hg-tab').forEach(tab => {
    tab.addEventListener('click', () => {
        document.querySelectorAll('.hg-tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        renderHydraGlow(tab.dataset.hgcat);
    });
});

// ── Init ──
initHgTracker();
renderHydraGlow('glow7');

