let exCurrentCategory = 'neck';
let exExercisesExplored = new Set();
let exModalData = null;
let exCurrentStep = 0;

function renderExercise(category) {
    exCurrentCategory = category;
    const grid = document.getElementById('exGrid');
    const exercises = EX_DATA[category];
    document.getElementById('exTotalCount').textContent = exercises.length;
    updateExProgress(exercises);

    grid.innerHTML = exercises.map((ex, i) => `
        <div class="ex-card ${exExercisesExplored.has(ex.id) ? 'explored' : ''}" 
             data-exid="${ex.id}"
             style="animation-delay: ${i * 0.08}s"
             onclick="openExModal('${ex.id}')">
            <div class="ex-card-img-wrap">
                ${(ex.steps[0].imgs[0] && typeof ex.steps[0].imgs[0] === 'object' && ex.steps[0].imgs[0].type === 'img')
                    ? `<img src="${ex.steps[0].imgs[0].src}" alt="${ex.name}" class="ex-card-thumb-img" />`
                    : `<div class="ex-card-emoji-big">${ex.icon}</div>`
                }
            </div>
            <div class="ex-card-body">
                <div class="ex-card-name">${ex.name}</div>
                <div class="ex-card-steps-label">${ex.steps.length} steps</div>
                <div class="ex-card-tap">👆 Tap to explore</div>
            </div>
        </div>
    `).join('');
}

function updateExProgress(exercises) {
    const explored = exercises.filter(e => exExercisesExplored.has(e.id)).length;
    document.getElementById('exDoneCount').textContent = explored;
    document.getElementById('exTotalCount').textContent = exercises.length;
    const pct = exercises.length ? (explored / exercises.length) * 100 : 0;
    document.getElementById('exProgressBar').style.width = pct + '%';
}

function openExModal(exId) {
    const category = Object.keys(EX_DATA).find(cat => EX_DATA[cat].find(e => e.id === exId));
    const ex = EX_DATA[category].find(e => e.id === exId);
    if (!ex) return;

    exModalData = ex;
    exCurrentStep = 0;

    document.getElementById('exModalIcon').textContent = ex.icon;
    document.getElementById('exModalTitle').textContent = ex.name;
    document.getElementById('exModalReps').textContent = '🔁 ' + ex.reps;

    renderExStep();

    document.getElementById('exModalOverlay').classList.add('show');
    document.getElementById('exModal').classList.add('show');
    document.body.style.overflow = 'hidden';
}

function renderExStep() {
    const ex = exModalData;
    const step = ex.steps[exCurrentStep];
    const stepper = document.getElementById('exStepper');

    function renderImgItem(item) {
        if (item && typeof item === 'object' && item.type === 'img') {
            return `<img src="${item.src}" alt="exercise step" class="ex-step-real-img" />`;
        }
        return `${item}`;
    }
    const imgsHTML = step.imgs.length > 1
        ? `<div class="ex-step-imgs">${step.imgs.map(e => `<div class="ex-step-img-box">${renderImgItem(e)}</div>`).join('')}</div>`
        : `<div class="ex-step-single-img">${renderImgItem(step.imgs[0])}</div>`;

    stepper.innerHTML = `
        <div class="ex-step active">
            ${imgsHTML}
            <div class="ex-step-num">${exCurrentStep + 1}</div>
            <div class="ex-step-text">${step.text}</div>
        </div>
    `;

    const isLast = exCurrentStep === ex.steps.length - 1;
    const isFirst = exCurrentStep === 0;

    document.getElementById('exStepCounter').textContent = `${exCurrentStep + 1} / ${ex.steps.length}`;
    document.getElementById('exPrevBtn').disabled = isFirst;
    document.getElementById('exNextBtn').textContent = isLast ? '✓ Done' : 'Next →';

    const badge = document.getElementById('exDoneBadge');
    if (isLast) {
        badge.classList.add('show');
        // Mark as explored
        exExercisesExplored.add(ex.id);
        updateExProgress(EX_DATA[exCurrentCategory]);
        // Update card
        const card = document.querySelector(`.ex-card[data-exid="${ex.id}"]`);
        if (card) card.classList.add('explored');
    } else {
        badge.classList.remove('show');
    }
}

function closeExModal() {
    document.getElementById('exModal').classList.remove('show');
    document.getElementById('exModalOverlay').classList.remove('show');
    document.body.style.overflow = '';
}

// Nav listeners
document.getElementById('exPrevBtn').addEventListener('click', () => {
    if (exCurrentStep > 0) { exCurrentStep--; renderExStep(); }
});
document.getElementById('exNextBtn').addEventListener('click', () => {
    if (exCurrentStep < exModalData.steps.length - 1) {
        exCurrentStep++;
        renderExStep();
    } else {
        closeExModal();
    }
});
document.getElementById('exModalClose').addEventListener('click', closeExModal);
document.getElementById('exModalOverlay').addEventListener('click', closeExModal);

// Tab switching
document.querySelectorAll('.ex-tab').forEach(tab => {
    tab.addEventListener('click', () => {
        document.querySelectorAll('.ex-tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        renderExercise(tab.dataset.excat);
    });
});

// Init
renderExercise('neck');
/* ═══════════════════════════════════════════════════
   SKINORA ONBOARDING — profile quiz
═══════════════════════════════════════════════════ */

var SK_PROFILE_KEY = 'skinoraProfileMale';

var skProfile = {
    skinType:  null,
    undertone: null,
    age:       null,
    height:    null,
    weight:    null,
    smoking:   null
};

function skIsMaleProfileComplete(p) {
    return !!(p && p.skinType && p.undertone && p.age && p.height && p.weight && p.smoking);
}

function skLoadSavedProfile() {
    try {
        var raw = localStorage.getItem(SK_PROFILE_KEY);
        if (raw) return JSON.parse(raw);
        var legacy = localStorage.getItem('skinoraProfile');
        if (legacy) {
            var p = JSON.parse(legacy);
            if (skIsMaleProfileComplete(p)) {
                localStorage.setItem(SK_PROFILE_KEY, legacy);
                return p;
            }
        }
    } catch (e) {}
    return null;
}

function skSaveProfile() {
    try {
        localStorage.setItem(SK_PROFILE_KEY, JSON.stringify(skProfile));
    } catch (e) {}
    if (window.SkinoraAPI && window.SkinoraAPI.getToken()) {
        window.SkinoraAPI.saveProfile(skProfile).catch(function () { /* ignore */ });
    }
}

function skSpawnParticles() {
    var container = document.getElementById('skParticles');
    if (!container || container.childElementCount > 0) return;
    var colors = ['#60a5fa','#818cf8','#38bdf8','#6366f1','#93c5fd','#a5b4fc'];
    for (var i = 0; i < 25; i++) {
        var p = document.createElement('div');
        p.className = 'sk-particle';
        var size  = 4 + Math.random() * 7;
        var dur   = 9 + Math.random() * 14;
        var delay = Math.random() * -22;
        var col   = colors[Math.floor(Math.random() * colors.length)];
        p.style.cssText = [
            'width:' + size + 'px;',
            'height:' + size + 'px;',
            'left:' + (Math.random() * 100) + '%;',
            'background:' + col + ';',
            'animation-duration:' + dur + 's;',
            'animation-delay:' + delay + 's;',
            'opacity:' + (0.3 + Math.random() * 0.5) + ';',
            'box-shadow:0 0 ' + (size * 2) + 'px ' + col + ';'
        ].join('');
        container.appendChild(p);
    }
}

function skShowOnboarding() {
    var overlay = document.getElementById('skOnboarding');
    if (!overlay) return;
    overlay.classList.remove('sk-hidden');
    overlay.style.opacity = '1';
    skGoTo(0);
    skSpawnParticles();
}

function skResetOnboardingUI() {
    ['skAge', 'skHeight', 'skWeight'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.value = '';
    });
    ['skNext1', 'skNext2', 'skNext3', 'skNext4'].forEach(function(id) {
        var btn = document.getElementById(id);
        if (btn) btn.disabled = true;
    });
    document.querySelectorAll('.sk-opt.picked').forEach(function(b) {
        b.classList.remove('picked');
    });
}

function skRestartOnboarding() {
    skProfile = {
        skinType: null, undertone: null, age: null,
        height: null, weight: null, smoking: null
    };
    window.skProfile = skProfile;
    try { localStorage.removeItem(SK_PROFILE_KEY); } catch (e) {}
    skResetOnboardingUI();
    skCloseProfile();
    skShowOnboarding();
}

// ── Navigate between steps ──────────────────────────
function skGoTo(step) {
    document.querySelectorAll('.sk-screen').forEach(function(s) {
        s.classList.remove('active');
    });
    var target = document.getElementById('skStep' + step);
    if (target) target.classList.add('active');

    // Update progress bar (steps 1-5 out of 5)
    var pct = step === 0 ? 0 : Math.round((step / 5) * 100);
    var bar = document.getElementById('skProgressFill');
    if (bar) bar.style.width = pct + '%';

    if (step === 5) skBuildSummary();
}

// ── Single-select pick ──────────────────────────────
function skPick(btn, field) {
    var grid = btn.closest('.sk-options');
    grid.querySelectorAll('.sk-opt').forEach(function(b) { b.classList.remove('picked'); });
    btn.classList.add('picked');
    skProfile[field] = btn.dataset.val;

    if (field === 'skinType') {
        var n = document.getElementById('skNext1');
        if (n) n.disabled = false;
    }
    if (field === 'undertone') {
        var n = document.getElementById('skNext2');
        if (n) n.disabled = false;
    }
    if (field === 'smoking') {
        var n = document.getElementById('skNext4');
        if (n) n.disabled = false;
    }
}

// ── Step 3 (stats) validation ───────────────────────
function skCheckStep3() {
    var age    = document.getElementById('skAge').value;
    var height = document.getElementById('skHeight').value;
    var weight = document.getElementById('skWeight').value;
    skProfile.age    = age    ? parseInt(age)    : null;
    skProfile.height = height ? parseInt(height) : null;
    skProfile.weight = weight ? parseInt(weight) : null;
    var n = document.getElementById('skNext3');
    if (n) n.disabled = !(age && height && weight);
}

// ── Step 4 (smoking) validation ──────────────────────
function skCheckStep4() {
    var n = document.getElementById('skNext4');
    if (n) n.disabled = !skProfile.smoking;
}

// ── Build summary pills on completion screen ────────
function skBuildSummary() {
    var labels = {
        skinType:  { oily:'Oily 💧', dry:'Dry 🌵', combination:'Combo ⚖️', sensitive:'Sensitive 🌸', normal:'Normal ✨' },
        undertone: { warm:'Warm 🌅', cool:'Cool ❄️', neutral:'Neutral 🌿', olive:'Olive 🫒' },
        smoking:   { smoke:'Smoker 🚬', vape:'Vaper 💨', nothing:'Non-Smoker ✅' }
    };
    var pills = [];
    if (skProfile.age)       pills.push('Age ' + skProfile.age);
    if (skProfile.height)    pills.push(skProfile.height + ' cm');
    if (skProfile.weight)    pills.push(skProfile.weight + ' kg');
    if (skProfile.skinType)  pills.push(labels.skinType[skProfile.skinType]   || skProfile.skinType);
    if (skProfile.undertone) pills.push(labels.undertone[skProfile.undertone] || skProfile.undertone);
    if (skProfile.smoking)   pills.push(labels.smoking[skProfile.smoking]     || skProfile.smoking);

    var el = document.getElementById('skDonePills');
    if (el) el.innerHTML = pills.map(function(p) {
        return '<span class="sk-pill">' + p + '</span>';
    }).join('');
}

// ── Enter dashboard ─────────────────────────────────
function skEnter() {
    var overlay = document.getElementById('skOnboarding');
    if (!overlay) return;
    overlay.style.transition = 'opacity 0.7s ease';
    overlay.style.opacity = '0';
    setTimeout(function() {
        overlay.classList.add('sk-hidden');
        window.skProfile = skProfile;
        skSaveProfile();
        skPopulateProfile();
        skToast();
    }, 700);
}

// ── Welcome back toast (returning user after login) ──
function skWelcomeBack() {
    var toast = document.createElement('div');
    toast.style.cssText = [
        'position:fixed;bottom:28px;left:50%;',
        'transform:translateX(-50%) translateY(80px);',
        'background:linear-gradient(135deg,#3b82f6,#6366f1);',
        'color:white;padding:0.9rem 2rem;border-radius:999px;',
        'font-weight:700;font-size:0.92rem;z-index:9998;',
        'box-shadow:0 8px 30px rgba(59,130,246,0.5);',
        'transition:transform 0.55s cubic-bezier(0.34,1.56,0.64,1),opacity 0.5s;',
        'white-space:nowrap;pointer-events:none;'
    ].join('');
    toast.textContent = 'Welcome back, King! Your dashboard is ready 💪';
    document.body.appendChild(toast);
    requestAnimationFrame(function() {
        toast.style.transform = 'translateX(-50%) translateY(0)';
    });
    setTimeout(function() {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(-50%) translateY(-18px)';
        setTimeout(function() { if (toast.parentNode) toast.remove(); }, 500);
    }, 4000);
}

// ── Welcome toast ────────────────────────────────────
function skToast() {
    var emoji = { oily:'💧', dry:'🌵', combination:'⚖️', sensitive:'🌸', normal:'✨' };
    var em = emoji[skProfile.skinType] || '✨';
    var toast = document.createElement('div');
    toast.style.cssText = [
        'position:fixed;bottom:28px;left:50%;',
        'transform:translateX(-50%) translateY(80px);',
        'background:linear-gradient(135deg,#3b82f6,#6366f1);',
        'color:white;padding:0.9rem 2rem;border-radius:999px;',
        'font-weight:700;font-size:0.92rem;z-index:9998;',
        'box-shadow:0 8px 30px rgba(59,130,246,0.5);',
        'transition:transform 0.55s cubic-bezier(0.34,1.56,0.64,1),opacity 0.5s;',
        'white-space:nowrap;pointer-events:none;'
    ].join('');
    toast.textContent = 'Welcome, King! ' + em + ' Your glow journey begins now 💪';
    document.body.appendChild(toast);
    requestAnimationFrame(function() {
        toast.style.transform = 'translateX(-50%) translateY(0)';
    });
    setTimeout(function() {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(-50%) translateY(-18px)';
        setTimeout(function() { if (toast.parentNode) toast.remove(); }, 500);
    }, 4000);
}

// ── Init on DOM ready ────────────────────────────────
document.addEventListener('DOMContentLoaded', function() {

    // Dark mode: restore saved preference
    try {
        if (localStorage.getItem('skinoraDark') === '1') {
            document.body.classList.add('dark-mode');
        }
    } catch(e) {}

    // Theme toggle
    var themeBtn = document.getElementById('themeToggle');
    if (themeBtn) {
        themeBtn.addEventListener('click', function() {
            document.body.classList.toggle('dark-mode');
            try { localStorage.setItem('skinoraDark', document.body.classList.contains('dark-mode') ? '1' : '0'); } catch(e) {}
        });
    }

    if (window.SkinoraAPI && window.SkinoraAPI.getToken()) {
        return;
    }

    var savedProfile = skLoadSavedProfile();
    if (skIsMaleProfileComplete(savedProfile)) {
        skProfile = savedProfile;
        window.skProfile = skProfile;
        var overlay = document.getElementById('skOnboarding');
        if (overlay) overlay.classList.add('sk-hidden');
        skPopulateProfile();
    } else {
        skShowOnboarding();
    }
});

window.skRestartOnboarding = skRestartOnboarding;
window.skShowOnboarding = skShowOnboarding;
window.skWelcomeBack = skWelcomeBack;
window.skProfile = skProfile;

// ── Refresh dashboard after FormaFace scan ─────────
function skRefreshDashProfile() {
    skPopulateProfile();
    if (typeof skRunEnhancements === 'function') skRunEnhancements();
}

// ── Populate profile UI from skProfile ───────────────
function skPopulateProfile() {
    var p = skProfile;

    // Labels
    var skinLabels = { oily:'Oily', dry:'Dry', combination:'Combination', sensitive:'Sensitive', normal:'Normal' };
    var toneLabels = { warm:'Warm', cool:'Cool', neutral:'Neutral', olive:'Olive' };
    var smokingLabels = { smoke:'Smoker', vape:'Vaper', nothing:'Non-Smoker' };
    var smokingIcons  = { smoke:'🚬', vape:'💨', nothing:'✅' };
    var skinIcons = { oily:'💧', dry:'🌵', combination:'⚖️', sensitive:'🌸', normal:'✨' };
    var toneIcons = { warm:'🌅', cool:'❄️', neutral:'🌿', olive:'🫒' };

    // ── Dashboard summary card ──
    var dashSub = [];
    if (p.age) dashSub.push('Age ' + p.age);
    if (p.skinType) dashSub.push((skinIcons[p.skinType] || '') + ' ' + (skinLabels[p.skinType] || p.skinType) + ' skin');
    if (p.undertone) dashSub.push((toneIcons[p.undertone] || '') + ' ' + (toneLabels[p.undertone] || p.undertone) + ' undertone');
    var dashSubEl = document.getElementById('skDashInfo');
    if (dashSubEl) {
        dashSubEl.querySelector('.sk-dash-name').textContent = 'My Glow Profile';
        dashSubEl.querySelector('.sk-dash-sub').textContent = dashSub.length ? dashSub.join(' · ') : 'Tap to view your profile';
    }
    // Restore DP on dash card
    try {
        var dp = localStorage.getItem('skinoraDp');
        if (dp) {
            var dashDp = document.getElementById('skDashDp');
            if (dashDp) { dashDp.innerHTML = '<img src="' + dp + '" alt="Profile photo">'; }
            var hdrAv = document.getElementById('headerAvatar');
            if (hdrAv) { hdrAv.innerHTML = '<img src="' + dp + '" alt="Profile photo">'; }
        }
    } catch(e) {}

    // ── Panel stats ──
    var statsEl = document.getElementById('skProfileStats');
    if (statsEl && (p.age || p.height || p.weight)) {
        var bmi = '';
        if (p.height && p.weight) {
            var h = p.height / 100;
            bmi = (p.weight / (h * h)).toFixed(1);
        }
        var stats = [];
        if (p.age)    stats.push({ val: p.age,    lbl: 'Age' });
        if (p.height) stats.push({ val: p.height + ' cm', lbl: 'Height' });
        if (p.weight) stats.push({ val: p.weight + ' kg', lbl: 'Weight' });
        if (bmi)      stats.push({ val: bmi, lbl: 'BMI' });
        statsEl.innerHTML = stats.map(function(s) {
            return '<div class="sk-stat-box"><div class="sk-stat-val">' + s.val + '</div><div class="sk-stat-lbl">' + s.lbl + '</div></div>';
        }).join('');
    }

    // ── Panel detail rows ──
    var detailsEl = document.getElementById('skProfileDetails');
    if (detailsEl) {
        var rows = [];
        if (p.skinType)  rows.push({ icon: skinIcons[p.skinType] || '✨', lbl: 'Skin Type',  val: skinLabels[p.skinType]   || p.skinType });
        if (p.undertone) rows.push({ icon: toneIcons[p.undertone] || '🎨', lbl: 'Undertone',  val: toneLabels[p.undertone]  || p.undertone });
        if (p.smoking)   rows.push({ icon: smokingIcons[p.smoking] || '🚬', lbl: 'Lifestyle',  val: smokingLabels[p.smoking] || p.smoking });
        detailsEl.innerHTML = rows.map(function(r) {
            return '<div class="sk-detail-row">' +
                '<div class="sk-detail-icon">' + r.icon + '</div>' +
                '<div><div class="sk-detail-lbl">' + r.lbl + '</div><div class="sk-detail-val">' + r.val + '</div></div>' +
                '</div>';
        }).join('');
    }

    // Restore DP in panel
    try {
        var dp2 = localStorage.getItem('skinoraDp');
        if (dp2) skSetDpUI(dp2);
    } catch(e) {}
}

// ── Open / Close profile panel ───────────────────────
function skOpenProfile() {
    document.getElementById('skProfileOverlay').classList.add('open');
    document.getElementById('skProfilePanel').classList.add('open');
}
function skCloseProfile() {
    document.getElementById('skProfileOverlay').classList.remove('open');
    document.getElementById('skProfilePanel').classList.remove('open');
}

// ── Upload DP ────────────────────────────────────────
function skUploadDP(event) {
    var file = event.target.files && event.target.files[0];
    if (!file) return;
    var reader = new FileReader();
    reader.onload = function(e) {
        var dataUrl = e.target.result;
        try { localStorage.setItem('skinoraDp', dataUrl); } catch(e2) {}
        skSetDpUI(dataUrl);
    };
    reader.readAsDataURL(file);
}
function skSetDpUI(dataUrl) {
    // Panel DP
    var img = document.getElementById('skDpImg');
    if (img) img.innerHTML = '<img src="' + dataUrl + '" alt="Profile photo">';
    // Dashboard card DP
    var dashDp = document.getElementById('skDashDp');
    if (dashDp) dashDp.innerHTML = '<img src="' + dataUrl + '" alt="Profile photo">';
    // Header avatar
    var hdrAv = document.getElementById('headerAvatar');
    if (hdrAv) hdrAv.innerHTML = '<img src="' + dataUrl + '" alt="Profile photo">';
}
// Male dashboard — Menstheal section removed
// ══════════════════════════════════════════════════════════════
//  NEUROCURE MODULE
// ══════════════════════════════════════════════════════════════
function ncSetMode(mode) {
    // Update mode card active states
    ['smoke','vape','clean'].forEach(function(m) {
        var card = document.getElementById('ncMode' + m.charAt(0).toUpperCase() + m.slice(1));
        if (card) card.classList.toggle('active', m === mode);
    });

    // Hide all panels
    ['ncPanelSmoke','ncPanelVape','ncPanelClean'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) { el.classList.remove('active'); }
    });

    // Show the right panel
    var panelMap = { smoke: 'ncPanelSmoke', vape: 'ncPanelVape', clean: 'ncPanelClean' };
    var target = document.getElementById(panelMap[mode]);
    if (target) {
        target.classList.add('active');
        // Scroll to panel smoothly
        setTimeout(function() {
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 80);
    }
}

// Auto-select mode based on onboarding smoking input if available
(function ncAutoInit() {
    try {
        var profile = skLoadSavedProfile() || {};
        var smoking = profile.smoking;
        if (smoking === 'smoke') ncSetMode('smoke');
        else if (smoking === 'vape') ncSetMode('vape');
        else if (smoking === 'nothing') ncSetMode('clean');
    } catch(e) {}
})();